window.ScripturaLexicons.BDAG_PART_0137 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epigrapho-bdag\" data-source=\"BDAG\" data-search=\"ἐπιγράφω epigráphō verbo escrever sobre; inscrever; registrar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιγράφω</td><td>verbo</td><td>escrever sobre; inscrever; registrar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epide-bdag\" data-source=\"BDAG\" data-search=\"ἔπιδε épide forma verbal; remissão ver ἐπεῖδον BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔπιδε</td><td>forma verbal; remissão</td><td>ver ἐπεῖδον</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epideiknumi-bdag\" data-source=\"BDAG\" data-search=\"ἐπιδείκνυμι epideíknumi verbo mostrar; indicar; demonstrar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιδείκνυμι</td><td>verbo</td><td>mostrar; indicar; demonstrar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epideomai-bdag\" data-source=\"BDAG\" data-search=\"ἐπιδέομαι epidéomai verbo necessitar; carecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιδέομαι</td><td>verbo</td><td>necessitar; carecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epidekhomai-bdag\" data-source=\"BDAG\" data-search=\"ἐπιδέχομαι epidékhomai verbo acolher; receber; aceitar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιδέχομαι</td><td>verbo</td><td>acolher; receber; aceitar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epidemeo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιδημέω epidēméō verbo permanecer como visitante; retornar para casa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιδημέω</td><td>verbo</td><td>permanecer como visitante; retornar para casa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epidemia-bdag\" data-source=\"BDAG\" data-search=\"ἐπιδημία, ας, ἡ epidēmía substantivo feminino estada; permanência temporária BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιδημία, ας, ἡ</td><td>substantivo feminino</td><td>estada; permanência temporária</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epidiatassomai-bdag\" data-source=\"BDAG\" data-search=\"ἐπιδιατάσσομαι epidiatássomai verbo acrescentar disposição; aditar testamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιδιατάσσομαι</td><td>verbo</td><td>acrescentar disposição; aditar testamento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epididomi-bdag\" data-source=\"BDAG\" data-search=\"ἐπιδίδωμι epidídōmi verbo dar; entregar; render-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιδίδωμι</td><td>verbo</td><td>dar; entregar; render-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epidiorthoo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιδιορθόω epidiorthóō verbo corrigir adicionalmente; pôr em ordem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιδιορθόω</td><td>verbo</td><td>corrigir adicionalmente; pôr em ordem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epidyo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιδύω epidýō verbo pôr-se; descer; declinar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιδύω</td><td>verbo</td><td>pôr-se; descer; declinar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epieikeia-bdag\" data-source=\"BDAG\" data-search=\"ἐπιείκεια, ας, ἡ epieíkeia substantivo feminino clemência; gentileza; indulgência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιείκεια, ας, ἡ</td><td>substantivo feminino</td><td>clemência; gentileza; indulgência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epieikes-bdag\" data-source=\"BDAG\" data-search=\"ἐπιεικής, ές epieikḗs adjetivo brando; gentil; cortês; tolerante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιεικής, ές</td><td>adjetivo</td><td>brando; gentil; cortês; tolerante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epieikia-bdag\" data-source=\"BDAG\" data-search=\"ἐπιεικία epieikía substantivo feminino; remissão ver ἐπιείκεια BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιεικία</td><td>substantivo feminino; remissão</td><td>ver ἐπιείκεια</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epizeteo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιζητέω epizētéō verbo procurar; investigar; desejar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιζητέω</td><td>verbo</td><td>procurar; investigar; desejar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epithanatios-bdag\" data-source=\"BDAG\" data-search=\"ἐπιθανάτιος, ον epithanátios adjetivo condenado à morte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιθανάτιος, ον</td><td>adjetivo</td><td>condenado à morte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epitheinai-epitheis-epithes-bdag\" data-source=\"BDAG\" data-search=\"ἐπιθεῖναι, ἐπιθείς, ἐπίθες epitheînai, epitheís, epíthes formas verbais; remissão ver ἐπιτίθημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιθεῖναι, ἐπιθείς, ἐπίθες</td><td>formas verbais; remissão</td><td>ver ἐπιτίθημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epithesis-bdag\" data-source=\"BDAG\" data-search=\"ἐπίθεσις, εως, ἡ epíthesis substantivo feminino imposição; ato de colocar sobre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπίθεσις, εως, ἡ</td><td>substantivo feminino</td><td>imposição; ato de colocar sobre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epithumeo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιθυμέω epithuméō verbo desejar ardentemente; cobiçar; ter desejo sexual BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιθυμέω</td><td>verbo</td><td>desejar ardentemente; cobiçar; ter desejo sexual</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epithumetes-bdag\" data-source=\"BDAG\" data-search=\"ἐπιθυμητής, οῦ, ὁ epithumētḗs substantivo masculino aquele que deseja; cobiçoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιθυμητής, οῦ, ὁ</td><td>substantivo masculino</td><td>aquele que deseja; cobiçoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-epigrapho-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγράφω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epigráphō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐπιγράψω</span>; primeiro aoristo <span class=\"greek\">ἐπέγραψα</span>, LXX. Passivo: segundo aoristo <span class=\"greek\">ἐπεγράφην</span>; perfeito <span class=\"greek\">ἐπιγέγραμμαι</span>; mais-que-perfeito passivo <span class=\"greek\">ἐπεγεγράμμην</span> (ver o verbete precedente; Homero e posteriores).</p>\n<p class=\"entry-text\"><b>① Formar letras ou palavras sobre qualquer espécie de superfície: escrever sobre, escrever em.</b></p>\n<p class=\"entry-text\"><b>ⓐ Literalmente.</b> <span class=\"greek\">ὀνόματα</span> <span class=\"greek\">ἐπιγεγραμμένα</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21:12</a> (cf. <span class=\"greek\">εἰς</span> <span class=\"greek\">χάρτην</span>, TestSol 18:25 P; cf. também Sig T). <span class=\"greek\">ἦν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπιγραφὴ</span> … <span class=\"greek\">ἐπιγεγραμμένη</span>, <i>a inscrição (= informação identificadora) … colocada sobre ele</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:26</a>; cf. GPt 4:11 (cf. Ael. Aristid. 50, 46 K. = 26, p. 516 D.: <span class=\"greek\">ἐπίγραμμα</span> <span class=\"greek\">ἐπιγέγραπται</span>). De uma inscrição dedicatória gravada em um altar, <span class=\"greek\">βωμὸς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">ἐπεγέγραπτο</span> (quanto a <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἐν</span>, cf. SIG 89, 24 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">στήλῃ</span>; 27; SIG² 588, 139; POxy 886, 16), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:23</a> (cf. SIG 814, 48 … <span class=\"greek\">βωμόν</span>, <span class=\"greek\">ἐπιγράφοντας</span> …). <span class=\"greek\">ῥάβδους</span> <span class=\"greek\">ἐπιγεγραμμένας</span> <span class=\"greek\">ἑκάστης</span> <span class=\"greek\">φυλῆς</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ὄνομα</span>, <i>varas assinaladas com o nome de cada tribo</i>, 1 Cl 43:2 (quanto à construção <span class=\"greek\">ἐ</span>. <span class=\"greek\">τί</span> <span class=\"greek\">τινος</span>, cf. Plut., Mor. 400e; quanto à ideia, Nm 17:16ss.; Diod. S. 13, 106, 9: bastão com uma <span class=\"greek\">ἐπιγραφή</span>).</p>\n<p class=\"entry-text\"><b>ⓑ Figuradamente, escrever em ou sobre,</b> com <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span> (cf. SIG 957, 68; 82; 1168, 7): <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">καρδίας</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:10</a> (Jr 38:33, variante de leitura; cf. Pv 7:3); <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">διάνοιαν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:16</a>.</p>\n<p class=\"entry-text\"><b>② Introduzir um nome num registro: registrar.</b> (Dem. 43, 15, «registrado como tutor»; POxy 231, 52 [séc. I d.C.]). Figuradamente, <span class=\"greek\">ἔργῳ</span> <span class=\"greek\">ἐπιγράφεσθαι</span>, <i>estar envolvido numa obra</i> (Socrat., Ep. 7, 2: <span class=\"greek\">μου</span> <span class=\"greek\">εἰπόντος</span>, <span class=\"greek\">ὡς</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἂν</span> … <span class=\"greek\">ἔργῳ</span> <span class=\"greek\">ἐπιγραφείην</span> <span class=\"greek\">ἀδίκῳ</span>; Appian., Bell. Civ. 1, 70 §323: <span class=\"greek\">ἔργοις</span> <span class=\"greek\">ἐπιγράφεσθαι</span> = <i>tomar parte em</i>); <span class=\"greek\">οὔτε</span> … <span class=\"greek\">κρείττονι</span> <span class=\"greek\">ἔργῳ</span> <span class=\"greek\">ἔχετε</span> <span class=\"greek\">ἐπιγραφῆναι</span>, <i>e não podeis (ver <span class=\"greek\">ἔχω</span> 5) ser identificados com nenhuma obra melhor</i>, IRo 2:1. <i>Inscrever</i> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">βίβλους</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ζώντων</span>, Hs 2:9. — M-M.</p></section></article>\n<article id=\"entry-epide-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔπιδε</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦épide⟧</span><span class=\"separator\">·</span><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Remissão:</b> <span class=\"greek\">ἔπιδε</span>: ver <span class=\"greek\">ἐπεῖδον</span>.</p></section></article>\n<article id=\"entry-epideiknumi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδείκνυμι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epideíknumi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐπιδείξω</span>; primeiro aoristo <span class=\"greek\">ἐπέδειξα</span>; particípio perfeito <span class=\"greek\">ἐπιδεδειχώς</span> (Ath. 20, 1); particípio passivo <span class=\"greek\">ἐπιδεδειγμένους</span>, 3 Mac 6:26, variante de leitura (Píndaro, Heródoto e posteriores).</p>\n<p class=\"entry-text\"><b>① Fazer que algo seja visto: mostrar, indicar.</b> Com <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, <i>algo a alguém</i> (IAndrosIsis, Kyme 22, <span class=\"greek\">Ἐγὼ</span> <span class=\"greek\">μυήσεις</span> <span class=\"greek\">ἀνθρώποις</span> <span class=\"greek\">ἐπέδειξα</span>, <i>eu [Ísis] dei a conhecer aos seres humanos as iniciações [nos ritos de mistério]</i>; Jos., Ant. 10, 31), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:19</a>; 24:1. <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖρας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:40</a>, variante de leitura; <span class=\"greek\">μαρτύριον</span>, MPol 1:1. <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἑαυτόν</span> <span class=\"greek\">τινι</span>, <i>mostrar-se a alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:14</a> (Appian., Mithrid. 89 §407: <span class=\"greek\">Ἀλέξανδρος</span> <span class=\"greek\">αὑτὸν</span> <span class=\"greek\">ἐπέδειξεν</span>). <span class=\"greek\">ἐ</span>. <span class=\"greek\">τινὶ</span> <span class=\"greek\">σημεῖον</span> <span class=\"greek\">ἐκ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανοῦ</span>, <i>mostrar a alguém (= fazer na presença de alguém) um sinal vindo do céu</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:1</a>; cf. GJs 8:3. <span class=\"greek\">ἵνα</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἐπιδείξῃ</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ἐπηγγείλατο</span> <span class=\"greek\">ὅραμα</span>, <i>para que me concedas ver a visão prometida</i>, Hv 3, 2, 3. Sem dativo: <span class=\"greek\">ὅλον</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἐπιδίξας</span>, <i>revelando-se completamente</i> (um leão), AcPl Ha 4, 29. Também a voz média com o mesmo significado: <i>mostrar</i> <span class=\"greek\">τ</span>. <span class=\"greek\">φυλάρχοις</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">σφραγῖδας</span>, 1 Cl 43:5 (cf. SIG 1157, 46s.). A média ocorre num sentido particular em <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:39</a>, <span class=\"greek\">ἐπιδεικνύμεναι</span> <span class=\"greek\">χιτῶνας</span>: as mulheres mostram as vestes sobre si mesmas, isto é, enquanto as estão usando (Socrat., Ep. 23, 3: <span class=\"greek\">τοιαῦτα</span> <span class=\"greek\">ἐπιδεικνύμενοι</span> = <i>mostrar tais coisas em si mesmo</i>).</p>\n<p class=\"entry-text\"><b>② Atribuir a alguma coisa determinada característica ou qualidade: apresentar como, representar.</b> Extensão figurada da acepção ① (Platão; Xen., Symp. 3, 3 e outros): <span class=\"greek\">τὸ</span> <span class=\"greek\">ψεῦδός</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἀληθὲς</span> <span class=\"greek\">ἐπέδειξα</span>, <i>apresentei minhas mentiras como verdade</i>, Hm 3:3.</p>\n<p class=\"entry-text\"><b>③ Demonstrar a veracidade de alguma coisa: demonstrar, provar, mostrar.</b> (Aristófanes, Platão e outros; Herm. Wr. 4, 7; PEleph 1, 7; PGiss 2 I, 24; LXX, especialmente 4 Mac; Just., D. 24, 1). Com <span class=\"greek\">τί</span>, <i>algo, apresentar prova</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:17</a>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἑαυτόν</span>, <i>revelar-se</i>, Dg 8:5; cf. versículo 6. Com <span class=\"greek\">τινί</span> seguido de interrogativa indireta, B 6:13. Seguido de <span class=\"greek\">ὅτι</span> (Fílon, Agr. 22), B 5:7. Com <span class=\"greek\">διά</span> <span class=\"greek\">τινος</span> (Jos., C. Ap. 2, 1: <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βιβλίου</span>), <span class=\"greek\">θεὸς</span> … <span class=\"greek\">διὰ</span> <span class=\"greek\">γνώσεως</span> <span class=\"greek\">ζωὴν</span> <span class=\"greek\">ἐπιδεικνύς</span>, <i>mostrando que a vida depende do conhecimento</i>, Dg 12:3; seguido de acusativo, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 18:28</a>. Igualmente a voz média (frequente em Fílon), 1 Cl 24:1; seguida de <span class=\"greek\">ὅτι</span>, MPol 2:2. — M-M; TW.</p></section></article>\n<article id=\"entry-epideomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδέομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epidéomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Segundo aoristo, segunda pessoa singular, <span class=\"greek\">ἐπεδεήθης</span>, Dt 2:7 (ver <span class=\"greek\">δέομαι</span>; Heródoto e outros; LXX; TestJob; Jos., C. Ap. 2, 192). <b>Precisar, necessitar, carecer</b>, com genitivo <span class=\"greek\">τινός</span>, <i>de alguma coisa</i> (Alex. Aphr., An. Mant. II 1, p. 163, 1: <span class=\"greek\">οὐδενὸς</span> <span class=\"greek\">ἐπιδεῖται</span> = <i>de nada necessita</i>; UPZ 59, 22 [108 a.C.]: <span class=\"greek\">πάντων</span>; Jó 6:22): <span class=\"greek\">τῆς</span> <span class=\"greek\">προσευχῆς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀγάπης</span>, IMg 14. A respeito de Deus: <span class=\"greek\">οὗ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐπιδέεται</span>, <i>de quem todas as coisas necessitam</i>, PtK 2. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐπιδεόμενοι</span>, <i>os necessitados</i> (Sir 34:21; TestJob 9:6), Dg 10:6. — DELG, s.v. 2 <span class=\"greek\">δέω</span>.</p></section></article>\n<article id=\"entry-epidekhomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδέχομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epidékhomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro, terceira pessoa singular, <span class=\"greek\">ἐπιδέξεται</span>, Sir 36:21; primeiro aoristo <span class=\"greek\">ἐπεδεξάμην</span>, LXX; particípio perfeito <span class=\"greek\">ἐπιδεδεγμένος</span>, 2 Mac 2:26; 3 Mac 6:26 (?) (Heródoto e outros; inscrições [frequentemente como termo técnico da aceitação de uma liturgia, mas também de pessoas homenageadas; ver Mitchell, adiante], papiros, LXX, TestIss 4:4, 6; EpArist; Fílon; Jos., Vi. 218).</p>\n<p class=\"entry-text\"><b>① Receber alguém na própria presença de maneira amistosa: receber, acolher.</b> Com <span class=\"greek\">τινά</span>, <i>alguém</i> (Políbio 21, 18, 3; Sb 12084 [séc. I d.C.]; POxy 281, 9 [20–50 d.C.]; 1 Mac 10:1; 12:8, 43 e outros), com nuance de cortesia diplomática, 3 Jo 9 e 10, a respeito de Diótrefes, que se recusa a reconhecer os emissários; cf. a passiva de Políbio e 1 Mac citada acima. Semelhantemente, no sentido de <i>receber</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.40\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:40</a> D (da recepção, por Paulo, do enviado Silas [ver versículo 27], e não uma leitura equivocada de <span class=\"greek\">ἐπιλεξάμενος</span>).</p>\n<p class=\"entry-text\"><b>② Reconhecer com receptividade: aceitar, não rejeitar.</b> (Políbio 6, 24, 7; UPZ 110, 161 [164 a.C.]; 1 Mac 10:46; Sir 51:26.) Com <span class=\"greek\">τινά</span>, <i>reconhecer a autoridade de alguém</i>, 3 Jo 9 (NRSV, com muitos intérpretes e versões; contudo, a ideia de «autoridade» não é defensável lexicalmente: ver ① e a refutação dessa tradução por M. Mitchell em JBL 117, 1998, pp. 299–320). — M-M.</p></section></article>\n<article id=\"entry-epidemeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδημέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epidēméō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">δῆμος</span>. Primeiro aoristo <span class=\"greek\">ἐπεδήμασα</span> (Tucídides e outros; inscrições, papiros, Fílon, Josefo, Justino). A ideia principal no emprego deste verbo é que o sujeito se encontra em trânsito com referência a determinado lugar de permanência; portanto, pode designar tanto estada fora de casa quanto retorno ao lar.</p>\n<p class=\"entry-text\"><b>① Permanecer em determinado lugar como estrangeiro ou visitante: estar na cidade, hospedar-se, permanecer.</b> (Xenofonte, Platão e outros; Jos., Vi. 200: <span class=\"greek\">Γαλιλαῖον</span> <span class=\"greek\">ἐπιδημοῦντα</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">Ἱεροσολύμοις</span>; UPZ 42 I, 4: <span class=\"greek\">ἐν</span> <span class=\"greek\">Μέμφει</span>; cf. Wilcken, APF 4, 1908, pp. 374, 422.) <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐπιδημοῦντες</span> <span class=\"greek\">Ῥωμαῖοι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:10</a>; <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ξένοι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:21</a> (IPriene 108, 286; 111, 187 [séc. I a.C.]: <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐπιδεδημηκότας</span> <span class=\"greek\">ξένους</span>). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">Ἐφέσῳ</span> <span class=\"greek\">ἐπιδημοῦντές</span> <span class=\"greek\">τινες</span> <span class=\"greek\">Κορίνθιοι</span>, <i>alguns coríntios estavam hospedados em Éfeso</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 18:27</a> D. <span class=\"greek\">ἐπιδημοῦντος</span> … <span class=\"greek\">σωτῆρος</span> (em oposição a <span class=\"greek\">ἀπαλλαγέντος</span>), <i>quando o Redentor estava [na terra]</i>, Qua.</p>\n<p class=\"entry-text\"><b>② Ir ao lugar em que normalmente se vive: voltar para casa.</b> (Xenofonte, Platão.) <span class=\"greek\">ὅταν</span> <span class=\"greek\">ἐπιδημήσῃς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">αὐτήν</span>, <i>quando voltares para casa, para ela</i>, Hs 1:9. — DELG, s.v. <span class=\"greek\">δῆμος</span>; M-M.</p></section></article>\n<article id=\"entry-epidemia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδημία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epidēmía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver o verbete precedente; Xenofonte, Platão e outros; inscrições, papiros; Fílon, In Flacc. 33; Jos., Ant. 8, 102. <b>Estado ou condição de permanecer numa região: estada, permanência temporária.</b> Da vida terrena: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμῳ</span> <span class=\"greek\">τούτῳ</span>, <i>nossa permanência (literalmente, «a permanência de nossa carne») neste mundo</i>, 2 Cl 5:5 (cf. Plut., Mor. 117f). — Sv.</p></section></article>\n<article id=\"entry-epidiatassomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδιατάσσομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epidiatássomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">διατάσσω</span>; somente em autores cristãos; ver O. Eger, ZNW 18 (1918), pp. 92s. <b>Acrescentar algo</b>, com a implicação de instruções suplementares ou modificadoras; termo técnico jurídico: <b>acrescentar um codicilo a um testamento</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:15</a>. — M. Conrat, ZNW 5 (1904), pp. 215s.; TW.</p></section></article>\n<article id=\"entry-epididomi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδίδωμι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epidídōmi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Imperfeito, terceira pessoa singular, <span class=\"greek\">ἐπεδίδου</span>; terceira pessoa plural <span class=\"greek\">ἐπεδίδουν</span>; <span class=\"greek\">ἐπέδοσαν</span>, Hs 8, 5, 4; futuro <span class=\"greek\">ἐπιδώσω</span>; primeiro aoristo <span class=\"greek\">ἐπέδωκα</span>; particípio do segundo aoristo <span class=\"greek\">ἐπιδούς</span>; perfeito <span class=\"greek\">ἐπιδέδωκα</span>. Passivo: primeiro aoristo <span class=\"greek\">ἐπεδόθην</span>; particípio perfeito <span class=\"greek\">ἐπιδεδομένος</span> (ver <span class=\"greek\">δίδωμι</span>; Homero e posteriores).</p>\n<p class=\"entry-text\"><b>① Efetuar a transferência de alguma coisa: dar, passar, entregar.</b> Com <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, <i>algo a alguém</i> (para uma refeição: Lucian., Symp. 36; inscrição de Abércio, linha 15): uma pedra, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:11</a>, variante de leitura; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:9</a>; uma serpente, versículo 10; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:11</a>; cf. um escorpião, versículo 12; uma porção de peixe, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:42</a>; pão, versículo 30; cf. <span class=\"greek\">ψωμίον</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.26\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13:26</a>, variante de leitura; uma carta, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.30\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:30</a> (cf. Diod. S. 14, 47, 2; Plut., Alex. 675 [19, 6]; PParis 20, 5; PEleph 15, 3; Jos., Ant. 15, 170); a terra de Canaã, AcPl Ha 8, 13. Emprego absoluto: <i>dar</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.35\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:35</a>, variante de leitura; Hv 3, 2, 5; Hs 8, 1, 2 e frequentemente; <span class=\"greek\">τινὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">χεῖρα</span>, Hv 1, 1, 2. Passivo: <span class=\"greek\">ἐπεδόθη</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">βιβλίον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">προφήτου</span> <span class=\"greek\">Ἠσαί̈ου</span>, <i>foi-lhe entregue o livro do profeta Isaías</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:17</a> (cf. Jos., Vi. 361: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">βιβλία</span>). <span class=\"greek\">λίθοι</span> <span class=\"greek\">ἦσαν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">παρθένων</span> <span class=\"greek\">ἐπιδεδομένοι</span>, Hs 9, 4, 6.</p>\n<p class=\"entry-text\"><b>② Ceder o controle de alguma coisa: entregar, abandonar, render-se.</b> (Tucídides 4, 11, 4; Plut., Mor. 319d; Ateneu 12, 29, 525e: <span class=\"greek\">εἰς</span> <span class=\"greek\">τρυφήν</span>.) <span class=\"greek\">ἑαυτόν</span> <span class=\"greek\">τινι</span> (Polyaenus 4, 6, 1; Alex. Aphr., Fat. 32, II/2, p. 204, 27; OGI 730, 7 [ver também Larfeld I 494]; Jos., Bell. 6, 56, Ant. 4, 42; <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἀληθείας</span> … <span class=\"greek\">τὰς</span> <span class=\"greek\">ψυχάς</span>, Ath. 3, 2), 1 Cl 14:2; 2 Cl 9:7. Emprego absoluto: <span class=\"greek\">ἐπιδόντες</span> <span class=\"greek\">ἐφερόμεθα</span>, <i>abandonamo-nos [ao vento] e nos deixamos levar</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:15</a> (cf. Lucian., Hermot. 28: <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πνεούσῃ</span>; ver também Alciphron 1, 10, 2). — M-M.</p></section></article>\n<article id=\"entry-epidiorthoo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδιορθόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epidiorthóō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">GDI 5039, 9 (Creta, séc. II a.C.); Themist., Or. 7, p. 113, 14; usualmente em escritores cristãos. Na única passagem em que ocorre em nossa literatura, atestam-se tanto o primeiro aoristo do subjuntivo médio <span class=\"greek\">ἐπιδιορθώσῃ</span> quanto o primeiro aoristo do subjuntivo ativo <span class=\"greek\">ἐπιδιορθώσῃς</span> (variante de leitura). <b>Pôr em ordem ou corrigir adicionalmente</b> (o que já fora corrigido): <span class=\"greek\">τὰ</span> <span class=\"greek\">λείποντα</span>, <i>o que ainda resta</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:5</a> (cf. Fílon, In Flacc. 124: <span class=\"greek\">ἡ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λειπομένων</span> <span class=\"greek\">ἐπανόρθωσις</span>). O sentido simples de <i>corrigir</i> também é provável (Philopon., In Aristot., An., p. 525, 26, 28, 30 Hayduck). — DELG, s.v. <span class=\"greek\">ὀρθός</span>; M-M.</p></section></article>\n<article id=\"entry-epidyo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epidýō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">De <span class=\"greek\">δύω</span>, «afundar»; ver <span class=\"greek\">δύσις</span>. Futuro médio, terceira pessoa singular, <span class=\"greek\">ἐπιδύσεται</span>, Dt 24:15; segundo aoristo, terceira pessoa singular, <span class=\"greek\">ἐπέδυ</span>, Jr 15:9 (com tmese já em Il. 2, 413; nos demais casos, LXX; Fílon, Spec. Leg. 3, 152: <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐπιδυέτω</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἥλιος</span>). <b>Descer, pôr-se (sobre)</b>, especialmente do movimento aparente do sol quando «se põe», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4:26</a> (Plut., Mor. 488c: <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἥλιον</span> <span class=\"greek\">δῦναι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">δεξιὰς</span> <span class=\"greek\">ἐμβαλόντες</span> <span class=\"greek\">ἀλλήλοις</span>, <i>antes de o sol se pôr, deram-se as mãos direitas</i> e separaram-se como amigos [costume dos pitagóricos quando tinham desavenças]; ver <span class=\"greek\">ἐπί</span> 18b). — DELG, s.v. <span class=\"greek\">δύω</span>.</p></section></article>\n<article id=\"entry-epieikeia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιείκεια, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epieíkeia⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver o verbete seguinte; W-H.: <span class=\"greek\">ἐπιεικία</span>; cf. Gignac I 297; Mlt-H. 348. <b>Qualidade de fazer concessões, apesar de circunstâncias que poderiam sugerir motivo para reação diferente: clemência, brandura, gentileza, graça, cortesia, indulgência, tolerância</b> (Tucídides; Aristóteles, EN 5, 14; Ps.-Platão, Def. 412b; Políbio 1, 14, 4; Herodiano 5, 1, 6; inscrições, papiros, LXX; En 5:6; Fílon, Mos. 1, 198; Jos., Ant. 6, 144; 15, 48), IPhld 1:1. <span class=\"greek\">τῇ</span> <span class=\"greek\">σῇ</span> <span class=\"greek\">ἐ</span>., <i>com a tua [costumeira] indulgência</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.4\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:4</a>. <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐπιεικείᾳ</span>, <i>mediante a gentileza</i>, IEph 10:3. Com <span class=\"greek\">πραΰτης</span> (Plut., Pericl. 173 [39, 1], Sertor. 581 [25, 6]; Appian., Basil. 1 §5; Fílon, Op. M. 103), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 10:1</a>; Dg 7:4; 1 Cl 30:8; com <span class=\"greek\">μακροθυμία</span>, 1 Cl 13:1; com <span class=\"greek\">ταπεινοφροσύνη</span>, 1 Cl 30:8; 56:1. <span class=\"greek\">μετ</span>’ <span class=\"greek\">ἐκτενοῦς</span> <span class=\"greek\">ἐπιεικείας</span>, <i>com perseverante tolerância</i>, 1 Cl 58:2; 62:2. <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ζῶντος</span>, <i>com toda a cortesia do Deus vivo</i>, IPhld 1:2 (<span class=\"greek\">ἐ</span>. como atributo de Deus: Dio Chrys. 80 [30], 19; Sb 12:18; Br 2:27; Dn 3:42; 2 Mac 2:22; EpArist 192; 207).</p>\n<p class=\"entry-text\">— A. von Harnack, «Sanftmut, Huld u. Demut» in d. alten Kirche: JKaftan Festschr. 1920, pp. 113ss.; L. Marshall, <i>Challenge of NT Ethics</i> (1947), pp. 305–308; C. Spicq, RB 54 (1947), pp. 333–339; F. Agostino, <i>Epieikia</i> (1973), especialmente pp. 100–137. Ver <span class=\"greek\">πραΰτης</span>, final. — DELG, s.v. <span class=\"greek\">ἔοικα</span>; M-M; TW; Spicq; Sv.</p></section></article>\n<article id=\"entry-epieikes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιεικής, ές</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epieikḗs⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver o verbete anterior; Homero e posteriores; inscrições, papiros [Mayser 92, 6]; LXX; PsSol 5:12; TestSol 1:1 VW; JosAs 1:5; códice A 15:8 e outros; EpArist; Fílon; Jos., C. Ap. 2, 211; Ar. 15, 5; Ath.; ver Mlt-H. 89; 314; 348. <b>Que não insiste em todos os direitos previstos pela letra da lei ou do costume: condescendente, brando, gentil, bondoso, cortês, tolerante</b> (assim Tucídides e outros; ver especialmente Aristóteles, EN 5, 10 [1137b], quanto à relação entre <span class=\"greek\">ἐ</span>. e <span class=\"greek\">δίκαιος</span>). Com <span class=\"greek\">ἄμαχος</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 3:3</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 3:2</a>. Com <span class=\"greek\">ἀγαθός</span>, provavelmente = <i>de boa índole, sensato</i> (como Diod. S. 16, 30, 2, visto que, em 16, 32, 2, <span class=\"greek\">ἀσεβής</span> se contrapõe a <span class=\"greek\">ἐπιεικής</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2:18</a>. Com <span class=\"greek\">εἰρηνικός</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3:17</a>. Com <span class=\"greek\">σώφρων</span> (Hyperid. 6, 5), 1 Cl 1:2. Com <span class=\"greek\">εὔσπλαγχνος</span>, 1 Cl 29:1 (acerca de Deus, como EpArist 211).</p>\n<p class=\"entry-text\"><span class=\"greek\">τὸ</span> <span class=\"greek\">ἐπιεικές</span> = <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπιείκεια</span> (Tucídides, Platão e outros; POxy 1218, 5; EpArist 188; Fílon, Somn. 2, 95: <span class=\"greek\">τὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δεσποτῶν</span> <span class=\"greek\">ἐ</span>.): <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ὑμῶν</span>, <i>vosso espírito tolerante</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4:5</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">γλώσσης</span> <span class=\"greek\">αὐτῶν</span>, <i>a brandura de sua língua</i>, 1 Cl 21:7. Neutro do comparativo empregado como advérbio (PTebt 484 [c. 14 d.C.]; Et 3:13b; Jos., Ant. 15, 14): <span class=\"greek\">ἐπιεικέστερον</span> <span class=\"greek\">λαλεῖν</span>, <i>falar mais brandamente</i>, Hm 12, 4, 2. — M-M; TW; Spicq; Sv.</p></section></article>\n<article id=\"entry-epieikia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιεικία</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epieikía⟧</span><span class=\"separator\">·</span><span>substantivo feminino; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Remissão:</b> <span class=\"greek\">ἐπιεικία</span>: ver <span class=\"greek\">ἐπιείκεια</span>.</p></section></article>\n<article id=\"entry-epizeteo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιζητέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epizētéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Imperfeito <span class=\"greek\">ἐπεζήτουν</span>; futuro <span class=\"greek\">ἐπιζητήσω</span>, LXX; primeiro aoristo <span class=\"greek\">ἐπεζήτησα</span>; aoristo passivo <span class=\"greek\">ἐπεζητήθην</span>, Tb 2:8 S (ver <span class=\"greek\">ζητέω</span>; Heródoto e posteriores).</p>\n<p class=\"entry-text\"><b>① Procurar descobrir alguma coisa: buscar, procurar, investigar.</b></p>\n<p class=\"entry-text\"><b>ⓐ Literalmente.</b> Com <span class=\"greek\">τινά</span>, <i>alguém</i> (PHamb 27, 4 [250 a.C.]: <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐπεζήτουν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐχ</span> <span class=\"greek\">ηὕρισκον</span>; Jos., Ant. 17, 295), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:42</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 12:19</a>.</p>\n<p class=\"entry-text\"><b>ⓑ Indagar, querer saber.</b> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θεότητος</span>, <i>indagar a respeito da divindade</i>, Hm 10, 1, 4 (com <span class=\"greek\">ἐρευνᾶν</span>); <span class=\"greek\">περὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μορφῶν</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">ἐπιζητεῖς</span>, <i>a respeito das formas sobre as quais indagaste</i>, Hv 3, 11, 1; <i>desejar conhecer alguma coisa</i> (Fílon, Spec. Leg. 1, 46), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:39</a>; Hs 6, 4, 1; 9, 16, 1.</p>\n<p class=\"entry-text\"><b>ⓒ Discutir, debater, disputar.</b> (Aristóteles, EN 9, 9, 2 [1169b, 13]: <span class=\"greek\">ἐπιζητεῖται</span> <span class=\"greek\">πότερον</span> … <span class=\"greek\">ἤ</span> = <i>discute-se se … ou</i>.) <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπιζητούμενα</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">πράγματα</span>, <i>os assuntos em controvérsia (ou em discussão) entre vós</i>, 1 Cl 1:1.</p>\n<p class=\"entry-text\"><b>② Ter sério interesse em algo ou desejar intensamente.</b></p>\n<p class=\"entry-text\"><b>ⓐ Desejar, querer.</b> Emprego absoluto, Dg 11:5. Com <span class=\"greek\">τί</span> (Diod. S. 17, 101, 6; Jos., Ant. 6, 149; 14, 407), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:32</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:30</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11:7</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4:17</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:14</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">μέλλουσαν</span> <span class=\"greek\">πόλιν</span>, <i>a cidade futura</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:14</a> (cf. Is 62:12). <span class=\"greek\">ζωήν</span>, <i>vida</i>, Dg 12:6. Seguido de infinitivo (Políbio 3, 57, 7; Diod. S. 19, 8, 4; PTebt 314, 6; TestJob 44:2), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:7</a>; Dg 11:2. <span class=\"greek\">τί</span> <span class=\"greek\">ἐπιζητεῖς</span>;, <i>que queres?</i>, Hs 7:1.</p>\n<p class=\"entry-text\"><b>ⓑ Desejar, querer.</b> (Teofrasto e outros; PLille 7, 6 [séc. III a.C.]; 1 Mac 7:13.) <span class=\"greek\">σημεῖον</span>, de pessoas que querem um sinal, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:39</a>; 16:4; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:29</a>, variante de leitura. — M-M; TW.</p></section></article>\n<article id=\"entry-epithanatios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιθανάτιος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epithanátios⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">θάνατος</span>; Dionísio de Halicarnasso 7, 35; Bel 31; Etym. Mag., p. 457, 40. <b>Referente a alguém condenado à morte: sentenciado à morte</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 4:9</a>. — TW.</p></section></article>\n<article id=\"entry-epitheinai-epitheis-epithes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιθεῖναι, ἐπιθείς, ἐπίθες</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epitheînai, epitheís, epíthes⟧</span><span class=\"separator\">·</span><span>formas verbais; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Remissão:</b> <span class=\"greek\">ἐπιθεῖναι</span>, <span class=\"greek\">ἐπιθείς</span>, <span class=\"greek\">ἐπίθες</span>: ver <span class=\"greek\">ἐπιτίθημι</span>.</p></section></article>\n<article id=\"entry-epithesis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίθεσις, εως, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epíthesis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Platão, Xenofonte e posteriores; inscrições, papiros, LXX, EpArist, Fílon; Jos., Ant. 18, 7, Vi. 293. <b>Ato de sobrepor alguma coisa a outra: imposição, colocação sobre</b> (assim Plutarco). <span class=\"greek\">τῶν</span> <span class=\"greek\">χειρῶν</span>, <i>imposição das mãos</i> (Fílon, Leg. All. 3, 90, Spec. Leg. 1, 203), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:18</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 4:14</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 1:6</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:2</a>.</p>\n<p class=\"entry-text\">— J. Behm, <i>D. Handauflegung im Urchristentum</i> (1911); H. Smith, AJT 17 (1913), pp. 47ss.; J. Coppens, <i>L’Imposition des mains et les Rites connexes dans le NT</i> (1925); F. Cabrol, «Impos. des mains», Dict. d’Arch. VII/1 (1926), pp. 391ss.; N. Adler, <i>Taufe u. Handauflegung</i> (<a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:14–17</a>), 1951; E. Lohse, <i>D. Ordination im Spätjudentum u. im NT</i> (1951); Billerb. II (1956), pp. 647–661; D. Daube, <i>The NT and Rabbinic Judaism</i> (1956), pp. 244–246; J. Jeremias, ZNW 52 (1961), pp. 101–104. — DELG, s.v. <span class=\"greek\">τίθημι</span>; M-M; TW; Spicq; Sv.</p></section></article>\n<article id=\"entry-epithumeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιθυμέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epithuméō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Imperfeito <span class=\"greek\">ἐπεθύμουν</span>; futuro <span class=\"greek\">ἐπιθυμήσω</span>; primeiro aoristo <span class=\"greek\">ἐπεθύμησα</span> (<span class=\"greek\">θυμέομαι</span>, «pôr o coração em alguma coisa»; Ésquilo, Heródoto e posteriores).</p>\n<p class=\"entry-text\"><b>① Ter forte desejo de fazer ou obter alguma coisa: desejar, ansiar por.</b> Com genitivo da coisa desejada (Heródoto 2, 66; Xen., Mem. 1, 6, 5; Êx 34:24; Sl 44:12; Pv 23:3, 6; EpArist 223; TestSol 16:2; ApcMos 6; Jos., Ant. 12, 309): prata, ouro, vestes, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.33\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:33</a>; uma boa obra, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 3:1</a>; coisas terrenas, 2 Cl 5:6; algo pertencente a outrem, Hs 1:11. Com acusativo da coisa (Teles, p. 42, 12; Diod. S. 37, 29, 2: <span class=\"greek\">τὸν</span> <span class=\"greek\">πλοῦτον</span>; Tetrast. Iamb. 2, 22, 1, p. 292; Mq 2:2; Sb 16:3; Sir 1:26; 16:1; 40:22; EpArist 211): <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλησίον</span>, D 2:3; cf. B 19:6 (Ar. 15, 4: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀλλότρια</span>); <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκοδομὴν</span> <span class=\"greek\">αὐτοῦ</span>, Hs 9, 9, 7; <span class=\"greek\">μηδέν</span>, IRo 4:3; <span class=\"greek\">κόσμον</span>, IRo 7:1; <span class=\"greek\">πονηρὸν</span> <span class=\"greek\">ἔργον</span>, Hv 1, 2, 4.</p>\n<p class=\"entry-text\">Seguido de infinitivo (Sófocles, Heródoto e outros; POxy 963; Is 58:2; Sus 15 Theod.; TestSol 9:2; TestJob 11:1; ApcSed 2:1; Jos., Bell. 6, 112; Just., D. 126, 6; Ath. 11, 2): <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:17</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:16</a>; 16:21; 17:22; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1:12</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:6</a>; B 16:10; Hs 9, 1, 10; 2 Cl 5:7; Pol 1:3; MPol 17:1; 19:1; AcPl Ha 2, 12. Seguido de acusativo e infinitivo, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:11</a>. Emprego absoluto (Is 58:11; 4 Mac 2:6; JosAs 24:18), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:7</a>; 13:9 (S. Lyonnet, OCullmann Festschr. [1962], pp. 157–165), ambos com referência a Êx 20:17; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 10:6</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4:2</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἐπιθυμίᾳ</span> <span class=\"greek\">ἐπιθυμεῖν</span>, <i>desejar ardentemente</i> (Gn 31:30; cf. Diod. S. 16, 61, 3: <span class=\"greek\">νόσῳ</span> <span class=\"greek\">νοσεῖν</span> = <i>estar gravemente enfermo</i>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:15</a>; GEb 308, 32; ver B-D-F §198, 6; Rob. 531; Mlt-H. 443s. <span class=\"greek\">ἐ</span>. <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span>, <i>desejar contra algo ou insurgir-se em protesto contra alguma coisa</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:17</a>.</p>\n<p class=\"entry-text\"><b>② Ter interesse sexual por alguém: desejar.</b> Com acusativo de pessoa (referindo-se a <span class=\"greek\">γυναῖκα</span>; cf. En 6:2): <span class=\"greek\">αὐτήν</span> (não se encontra no grego antigo, mas é usado em Êx 20:17; cf. Sir 1:26. Falta em algumas testemunhas; outras apresentam <span class=\"greek\">αὐτῆς</span>, em conformidade com Xen., An. 4, 1, 14; Dt 21:11; Sus 8; Fílon, Spec. Leg. 3, 66; Just., D. 134, 1): <i>desejá-la ardentemente, desejá-la com lascívia</i> (isto é, a mulher de outro; ver Betz, SM ad loc.), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:28</a> (cf. Êx 20:17; Dt 5:21; 4 Mac 2:5; lâmina de maldição de Hadrumeto, linhas 44s.: Dssm., B 31 [BS 274ss., ver p. 277] e IDefixWünsch 5, pp. 25s.: <span class=\"greek\">μηδεμίαν</span> <span class=\"greek\">ἄλλην</span> <span class=\"greek\">γυναῖκα</span> <span class=\"greek\">μήτε</span> <span class=\"greek\">παρθένον</span> <span class=\"greek\">ἐπιθυμοῦντα</span>). Cf. Hv 1, 1, 4. Com genitivo de pessoa, Hs 9, 13, 8. — B. 1162; DELG, s.v. <span class=\"greek\">θυμός</span>; M-M; TW.</p></section></article>\n<article id=\"entry-epithumetes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιθυμητής, οῦ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epithumētḗs⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver o verbete precedente; Heródoto 7, 6 e outros; LXX; Jos., C. Ap. 2, 45; Ar. <b>Aquele que deseja</b>, também em sentido pejorativo (BGU 531 II, 22 [séc. I d.C.]: <span class=\"greek\">οὔτε</span> <span class=\"greek\">εἰμὶ</span> <span class=\"greek\">ἄδικος</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">ἀλλοτρίων</span> <span class=\"greek\">ἐπιθυμητής</span> [quanto a <span class=\"greek\">ἀλλοτρ</span>. <span class=\"greek\">ἐπιθυμ</span>., ver Vett. Val., índice III, p. 397]; Pv 1:22). <span class=\"greek\">κακῶν</span>, <i>desejoso do mal</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 10:6</a> (Nm 11:34). <span class=\"greek\">μὴ</span> <span class=\"greek\">γίνου</span> <span class=\"greek\">ἐ</span>., <i>não sejas lascivo</i>, D 3:3. — M-M; TW.</p></section></article>"};
